INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DevOps nur eine Sammlung von Tools?', 2, '[{"text": "Nein", "correct": true, "because": "Es ist ein kultureller Ansatz"}, {"text": "Ja", "correct": false, "because": "Tools sind nur Teil davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesem Ansatz?', 3, '[{"text": "Schnellere Bereitstellung", "correct": true, "because": "Fördert Agilität"}, {"text": "Maximale Kontrolle", "correct": false, "because": "Fokus auf Automatisierung"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Doku bleibt wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken gehören zu DevOps?', 5, '[{"text": "Continuous Integration", "correct": true, "because": "Regelmäßige Code-Updates"}, {"text": "Continuous Deployment", "correct": true, "because": "Automatisierte Releases"}, {"text": "Manuelle Tests", "correct": false, "because": "Automatisierung im Fokus"}, {"text": "Silo-Strukturen", "correct": false, "because": "Fördert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DevOps fördert Teamarbeit. b) Es ersetzt Entwickler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entwickler bleiben essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich DevOps einführe?', 4, '[{"text": "Automatisierung", "correct": false, "because": "Kern von DevOps"}, {"text": "Kommunikation", "correct": false, "because": "Fördert Zusammenarbeit"}, {"text": "Manuelle Prozesse", "correct": true, "because": "Ziel ist Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DevOps nur für Cloud geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht cloudabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist typisch für diesen Ansatz?', 3, '[{"text": "Jenkins", "correct": true, "because": "Unterstützt CI/CD"}, {"text": "Photoshop", "correct": false, "because": "Design-Tool"}, {"text": "Excel", "correct": false, "because": "Kein DevOps-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt DevOps?', 5, '[{"text": "Schnellere Releases", "correct": true, "because": "CI/CD verkürzt Zyklen"}, {"text": "Bessere Qualität", "correct": true, "because": "Tests integriert"}, {"text": "Mehr Hardware", "correct": false, "because": "Fokus auf Prozesse"}, {"text": "Weniger Teamwork", "correct": false, "because": "Fördert Kollaboration"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DevOps verbindet Dev und Ops. b) Es macht Tests überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests sind zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DevOps?', 4, '[{"text": "CI/CD-Pipelines", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Monitoring", "correct": false, "because": "Sichert Stabilität"}, {"text": "Manuelle Deployments", "correct": true, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DevOps ein Jobtitel?', 2, '[{"text": "Nein", "correct": true, "because": "Es ist eine Methodik"}, {"text": "Ja", "correct": false, "because": "Rollen können daraus entstehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern diesen Ansatz?', 4, '[{"text": "Automatisierung", "correct": true, "because": "Reduziert Fehler"}, {"text": "Kollaboration", "correct": true, "because": "Bricht Silos auf"}, {"text": "Manuelle Kontrolle", "correct": false, "because": "Widerspricht DevOps"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DevOps nur für große Teams ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DevOps?', 3, '[{"text": "Automatisierung", "correct": true, "because": "Steigert Effizienz"}, {"text": "Maximale Dokumentation", "correct": false, "because": "Pragmatisch nötig"}, {"text": "Einzelarbeit", "correct": false, "because": "Teamwork im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DevOps nutzt CI/CD. b) Es verlangsamt Prozesse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prozesse werden beschleunigt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen DevOps?', 5, '[{"text": "Docker", "correct": true, "because": "Containerisierung"}, {"text": "Kubernetes", "correct": true, "because": "Orchestrierung"}, {"text": "Word", "correct": false, "because": "Kein DevOps-Tool"}, {"text": "Paint", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DevOps unwichtig?', 3, '[{"text": "Feedback-Schleifen", "correct": false, "because": "Verbessern Prozesse"}, {"text": "Teamkollaboration", "correct": false, "because": "Kernprinzip"}, {"text": "Manuelle Updates", "correct": true, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht DevOps die Fehlerquote?', 3, '[{"text": "Nein", "correct": true, "because": "Tests reduzieren Fehler"}, {"text": "Ja", "correct": false, "because": "Qualität im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DevOps auch für kleine Projekte taugt?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar und flexibel"}, {"text": "Nein", "correct": false, "because": "Nicht größenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für DevOps zentral?', 4, '[{"text": "Automatisierte Pipelines", "correct": true, "because": "Sichern schnelle Releases"}, {"text": "Manuelle Freigaben", "correct": false, "because": "Widerspricht DevOps"}, {"text": "Lokale Server", "correct": false, "because": "Cloud oft bevorzugt"}]');
